package events

import (
	"database/sql"
	"encoding/json"
	"errors"
)

// Lookup statuses reported per queried id.
const (
	// LookupFound names an id whose change is still in the online log.
	LookupFound = "found"
	// LookupMissing names an id the document has never held a row or a
	// retained summary for.
	LookupMissing = "missing"
	// LookupCompacted names an id whose online row was trimmed by
	// compaction; only its retained summary survives.
	LookupCompacted = "compacted"
)

// ChangeLookup is the answer for one id of a GetChangesByIDs batch, in the
// batch's request order. Status is LookupFound, LookupMissing or
// LookupCompacted.
//
// A found answer carries the online row's originating device, the payload
// exactly as it was stored at commit time and the cursor it was first
// assigned. A compacted answer carries only that first cursor from the
// retained summary — DeviceID and Payload are left empty and never restored.
// A missing answer carries nothing but the id and its status.
type ChangeLookup struct {
	ID       string
	Status   string
	DeviceID string
	Payload  json.RawMessage
	Cursor   int64
}

// GetChangesByIDs answers a read-only batch lookup of change ids for
// documentID in exactly the order given. The gate (registration then
// permission) is taken first inside one serialized transaction — an
// unregistered device yields store.ErrDeviceNotFound and a revoked device
// store.ErrPermissionDenied, before any change content is observed. Then each
// id is answered independently:
//
//   - an id with an online row is LookupFound with its device, verbatim
//     stored payload and first cursor;
//   - an id whose row compaction trimmed is LookupCompacted, reporting only
//     the first cursor held in its retained summary — no payload is restored
//     and the summary takes no part in any read other than this verdict;
//   - any other id (one the document has never known, an unknown document
//     included) is LookupMissing.
//
// Ids may repeat positionally in the answer only when the caller supplied
// them repeatedly; the HTTP layer rejects in-batch duplicates before this
// runs. The read starts a transaction but writes nothing, allocates no
// cursor, creates no change and notifies no waiter or subscriber, so it
// cannot move a cursor or wake a parked poll. The verdicts derive solely from
// durable rows and are therefore byte-stable across a process restart.
func (s *Service) GetChangesByIDs(documentID, deviceID string, ids []string) ([]ChangeLookup, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	// Gate first, exactly as the gated reads do: the device row and the
	// permission row are read before any change id is observed, so a rejected
	// query cannot reveal content.
	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return nil, err
	}

	out := make([]ChangeLookup, len(ids))
	for i, id := range ids {
		out[i] = ChangeLookup{ID: id, Status: LookupMissing}

		var device string
		var payload []byte
		var cursor int64
		err := tx.QueryRow(
			`SELECT device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND id = ?`,
			documentID, id,
		).Scan(&device, &payload, &cursor)
		switch {
		case errors.Is(err, sql.ErrNoRows):
			// No online row: a compaction-trimmed id keeps a retained summary
			// that still records its first cursor. Anything else never existed.
			var trimmedCursor int64
			err := tx.QueryRow(
				`SELECT cursor FROM change_identities
				 WHERE document_id = ? AND id = ?`,
				documentID, id,
			).Scan(&trimmedCursor)
			switch {
			case errors.Is(err, sql.ErrNoRows):
				// Stays LookupMissing with a zero value.
			case err != nil:
				return nil, err
			default:
				out[i] = ChangeLookup{
					ID:     id,
					Status: LookupCompacted,
					Cursor: trimmedCursor,
				}
			}
		case err != nil:
			return nil, err
		default:
			out[i] = ChangeLookup{
				ID:       id,
				Status:   LookupFound,
				DeviceID: device,
				Payload:  json.RawMessage(payload),
				Cursor:   cursor,
			}
		}
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}
	return out, nil
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strings"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// changeLookupRequest is the body of POST .../changes/query: the calling
// device and the non-empty, in-batch-unique set of change ids to answer. The
// device identity uses the same declaration the document-level change commit
// uses — no new authentication is introduced.
type changeLookupRequest struct {
	DeviceID string   `json:"deviceId"`
	IDs      []string `json:"ids"`
}

// changeLookupItem fixes the on-the-wire key order of one answer to id,
// status, then (for a found row) deviceId, payload and cursor. The
// device/payload/cursor fields are omitted entirely on missing and compacted
// answers: a compacted id reports only its first cursor, so it carries
// cursor alone alongside id and status, and a missing id carries nothing but
// its id and status.
type changeLookupItem struct {
	ID       string          `json:"id"`
	Status   string          `json:"status"`
	DeviceID string          `json:"deviceId,omitempty"`
	Payload  json.RawMessage `json:"payload,omitempty"`
	Cursor   int64           `json:"cursor,omitempty"`
}

// changeLookupResponse is the query body with the top-level key order fixed
// to results then count; count always equals the number of result entries,
// which equals the number of ids asked for.
type changeLookupResponse struct {
	Results []changeLookupItem `json:"results"`
	Count   int                `json:"count"`
}

// handleQueryChanges is the read-only batch lookup over a document's change
// collection:
//
//	POST /v1/documents/{documentID}/changes/query
//
// The strict application/json body names the calling device and a non-empty
// array of non-empty, in-batch-unique change ids; answers arrive in the exact
// order the ids were given. Each id is answered independently:
//
//   - "found": the change is still in the online log, so the answer carries
//     its originating device, the payload verbatim as it was saved at commit
//     time and its first cursor;
//   - "compacted": compaction trimmed the row, so the answer reports only the
//     first cursor held in its retained summary — no payload is restored and
//     the summary never participates in an ordinary read;
//   - "missing": the id has never belonged to the document, so the answer
//     carries no content. A missing id is a normal answer, not an error.
//
// The verdict order is request shape (400) first — content type, JSON
// validity, trailing content, a missing or empty ids array, an empty or
// mistyped element and an in-batch duplicate — then device existence (404)
// and document permission (403). A 404 or 403 exposes no change content. The
// query creates no change, allocates no cursor and wakes neither a long poll
// nor a push subscriber. Success is one compact JSON line ending in a
// newline with results then count.
func handleQueryChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	documentID := r.PathValue("documentID") // route pattern + guard guarantee non-empty

	var req changeLookupRequest
	if !decodeJSONBody(w, r, &req) {
		return
	}
	// Shape checks all precede the device existence verdict, so a malformed
	// query against an unregistered device is still a 400.
	if req.DeviceID == "" {
		writeError(w, http.StatusBadRequest, "deviceId must be a non-empty string")
		return
	}
	// A missing (nil) or empty ids array is the same request-shape error; a
	// non-string element was already rejected while decoding the JSON.
	if len(req.IDs) == 0 {
		writeError(w, http.StatusBadRequest, "ids must be a non-empty array of non-empty strings")
		return
	}
	seen := make(map[string]struct{}, len(req.IDs))
	for _, id := range req.IDs {
		if id == "" {
			writeError(w, http.StatusBadRequest, "each id must be a non-empty string")
			return
		}
		if _, dup := seen[id]; dup {
			writeError(w, http.StatusBadRequest, "duplicate change id within batch: "+id)
			return
		}
		seen[id] = struct{}{}
	}

	lookups, err := s.GetChangesByIDs(documentID, req.DeviceID, req.IDs)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			writeError(w, http.StatusNotFound, "device not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		default:
			writeError(w, http.StatusInternalServerError, "failed to look up changes")
		}
		return
	}

	items := make([]changeLookupItem, len(lookups))
	for i, l := range lookups {
		items[i] = changeLookupItem{
			ID:       l.ID,
			Status:   l.Status,
			DeviceID: l.DeviceID,
			Payload:  l.Payload,
			Cursor:   l.Cursor,
		}
	}
	writeJSON(w, http.StatusOK, changeLookupResponse{Results: items, Count: len(items)})
}

// malformedChangeQueryPath reports whether p targets the change-log batch
// lookup but is not at its exact location
// (/v1/documents/{documentID}/changes/query): a missing "changes" segment, an
// extra segment, a trailing slash (an empty trailing segment), or a "query"
// segment in a position short of the registered shape. ServeMux would answer
// those with a redirect or a plain-text 404/405; every failure of this
// endpoint must be a JSON 400 instead and never a redirect. Empty segments
// are already rejected by the guard itself.
//
// "query" is treated as the endpoint keyword only in its terminal segment
// position (the third segment, index 2); a document identifier literally
// named "query" occupies an identifier position (index 0) and keeps its
// ordinary routes.
func malformedChangeQueryPath(p string) bool {
	rest, ok := strings.CutPrefix(p, "/v1/documents/")
	if !ok {
		return false
	}
	segs := strings.Split(rest, "/")
	// The CRDT namespace ("crdt" immediately past the document identifier)
	// has its own guards; "query" there is an ordinary identifier.
	if len(segs) >= 2 && segs[1] == "crdt" {
		return false
	}
	// The named-snapshot-version subtree owns its own shape verdict.
	if len(segs) >= 3 && segs[0] != "" && segs[1] == "snapshots" && segs[2] == "versions" {
		return false
	}
	for i, seg := range segs {
		if seg != "query" {
			continue
		}
		// Identifier position: a document named "query" is an ordinary id.
		if i == 0 {
			continue
		}
		// Endpoint keyword position: the third segment must be exactly
		// "query" with a non-empty documentID and "changes" around it, and no
		// segment may follow. Any other occurrence is a malformed path.
		if i == 2 && len(segs) == 3 &&
			segs[0] != "" &&
			segs[1] == "changes" {
			return false
		}
		return true
	}
	return false
}

package server

import (
	"encoding/json"
	"errors"
	"net/http"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// handleSessionCompactChanges is the session-scoped change-log compaction
// entry, mounted one segment below the session document's change collection:
//
//	POST /v1/sessions/{sessionId}/documents/{documentId}/changes/compact
//
// It is the session view's counterpart to
// POST /v1/documents/{documentID}/changes/compact and shares its boundary,
// trimming, idempotency and persistence semantics byte-for-byte; only the
// caller identity differs. The calling device is the session's owning device,
// resolved from the path with the same identity rule as the session reads,
// exports, commits, replays, merges, polls and subscriptions — no new
// credential is introduced. The body carries no device field: a stray
// deviceId is decoded and ignored like every other unknown field, so it can
// never override the session owner. The body only has to be one legal JSON
// value — an object, array, scalar or null all compact identically; its
// content never affects the boundary or the removed count.
//
// Checks run in the fixed order request shape (400), session existence (404),
// document permission (403). The permission verdict is taken inside the
// compaction transaction, so a revoked device writes nothing and a rejected
// request observes no change content. On success the answer is 200 with one
// compact JSON line — boundary, then removed — terminated by a newline, the
// same compactChangesResponse the document-level entry emits. Compaction is
// idempotent, allocates no cursor, writes no change and wakes no waiter or
// subscriber.
func handleSessionCompactChanges(s *app.App, w http.ResponseWriter, r *http.Request) {
	sessionID := r.PathValue("sessionId")   // route pattern + guard guarantee non-empty
	documentID := r.PathValue("documentId") // route pattern + guard guarantee non-empty

	// The body carries no meaningful field: it only has to be exactly one
	// legal JSON value. Decoding into a RawMessage accepts an object, array,
	// scalar or null, while a missing/empty body, malformed JSON, trailing
	// content or a wrong Content-Type still fail the strict shared decoder.
	var body json.RawMessage
	if !decodeJSONBody(w, r, &body) {
		return
	}

	// Request shape is settled; only now does the session lookup run, so a
	// malformed body against an unknown session is still a 400.
	deviceID, err := s.SessionDevice(sessionID)
	if err != nil {
		if errors.Is(err, store.ErrSessionNotFound) {
			writeError(w, http.StatusNotFound, "session not found")
			return
		}
		writeError(w, http.StatusInternalServerError, "failed to look up session")
		return
	}

	boundary, removed, err := s.CompactSessionChanges(documentID, deviceID)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDeviceNotFound):
			// The session's device was deregistered between the lookup and the
			// compaction; its cascade removed the session too, so the identity
			// the caller used no longer exists.
			writeError(w, http.StatusNotFound, "session not found")
		case errors.Is(err, store.ErrPermissionDenied):
			writeError(w, http.StatusForbidden, "device permission for this document has been revoked")
		default:
			writeError(w, http.StatusInternalServerError, "failed to compact changes")
		}
		return
	}

	writeJSON(w, http.StatusOK, compactChangesResponse{Boundary: boundary, Removed: removed})
}

