33		// Hits are answered in the order asked, each carrying source device,
34		// verbatim saved payload and cursor. The body is one compact line with
35		// top-level keys results,count and item keys id,status,deviceId,payload,cursor.
36		w := queryChanges(t, h, "doc1", `{"deviceId":"dev","ids":["c","a","nope","b"]}`)
37		if w.Code != http.StatusOK {
38			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
