45			`{"id":"a","status":"found","deviceId":"dev","payload":{"k":"v"},"cursor":1},` +
46			`{"id":"nope","status":"missing"},` +
47			`{"id":"b","status":"found","deviceId":"dev","payload":42,"cursor":2}` +
48			`],"count":4}` + "\n"
49		if w.Body.String() != want {
