118	// Every request-shape violation is a 400 JSON error with zero writes, checked
119	// before the device even exists.
120	func TestQueryChangesHTTPRejectsBadShape(t *testing.T) {
121		h, _ := newTestHandler(t)
122		registerDevice(t, h, "dev")
123		url := "/v1/documents/doc1/changes/query"
124	
125		send := func(contentType, raw string) *httptest.ResponseRecorder {
126			r := httptest.NewRequest(http.MethodPost, url, strings.NewReader(raw))
127			if contentType != "" {
128				r.Header.Set("Content-Type", contentType)
129			}
130			w := httptest.NewRecorder()
131			h.ServeHTTP(w, r)
132			return w
133		}
134	
135		cases := []struct {
136			name        string
137			contentType string
138			body        string
139		}{
140			{"wrong content type", "text/plain", `{"deviceId":"dev","ids":["a"]}`},
141			{"missing content type", "", `{"deviceId":"dev","ids":["a"]}`},
142			{"content type with json suffix", "application/vnd.api+json", `{"deviceId":"dev","ids":["a"]}`},
143			{"invalid json", "application/json", `{"deviceId":"dev","ids":[`},
144			{"trailing content", "application/json", `{"deviceId":"dev","ids":["a"]} junk`},
145			{"second json value", "application/json", `{"deviceId":"dev","ids":["a"]}{}`},
146			{"missing ids", "application/json", `{"deviceId":"dev"}`},
147			{"null ids", "application/json", `{"deviceId":"dev","ids":null}`},
148			{"empty ids", "application/json", `{"deviceId":"dev","ids":[]}`},
149			{"empty id element", "application/json", `{"deviceId":"dev","ids":["a",""]}`},
150			{"non-string id element", "application/json", `{"deviceId":"dev","ids":["a",1]}`},
151			{"ids not an array", "application/json", `{"deviceId":"dev","ids":"a"}`},
152			{"duplicate ids", "application/json", `{"deviceId":"dev","ids":["a","a"]}`},
153			{"missing deviceId", "application/json", `{"ids":["a"]}`},
154			{"empty deviceId", "application/json", `{"deviceId":"","ids":["a"]}`},
155			{"non-string deviceId", "application/json", `{"deviceId":7,"ids":["a"]}`},
156			{"non-object body", "application/json", `[1,2]`},
157		}
158		for _, tc := range cases {
159			t.Run(tc.name, func(t *testing.T) {
160				w := send(tc.contentType, tc.body)
161				if w.Code != http.StatusBadRequest {
162					t.Fatalf("status = %d want 400 body = %s", w.Code, w.Body.String())
163				}
164				if ct := w.Header().Get("Content-Type"); ct != "application/json" {
165					t.Fatalf("content type = %q", ct)
166				}
167				if !strings.HasPrefix(w.Body.String(), `{"error":`) {
168					t.Fatalf("body = %q, want a JSON error", w.Body.String())
169				}
170			})
171		}
