173		// A malformed body against an unregistered device is still a 400: shape
174		// validation precedes device existence.
175		w := send("application/json", `{"deviceId":"ghost","ids":[]}`)
176		if w.Code != http.StatusBadRequest {
177			t.Fatalf("shape-before-existence = %d body = %s", w.Code, w.Body.String())
178		}
