253		if err != nil {
254			t.Fatal(err)
255		}
256		if len(rows) != 2 || next != 2 || rows[1].Cursor != 2 {
257			t.Fatalf("query moved the cursor: rows=%+v next=%d", rows, next)
258		}
259	}
260	
261	// Method and path shape: only POST at the exact .../changes/query location is
262	// accepted; every other verb or shape is a JSON 400, never a redirect.
263	func TestQueryChangesHTTPMethodAndPath(t *testing.T) {
264		h, _ := newTestHandler(t)
265	
266		cases := []struct {
267			method string
268			path   string
269		}{
270			{http.MethodGet, "/v1/documents/doc1/changes/query"},
271			{http.MethodPut, "/v1/documents/doc1/changes/query"},
