273			{http.MethodPost, "/v1/documents/doc1/changes/query/"},
274			{http.MethodPost, "/v1/documents/doc1/changes/query/extra"},
275			{http.MethodPost, "/v1/documents/doc1/changes/queryextra"},
276			{http.MethodPost, "/v1/documents//changes/query"},
277			{http.MethodPost, "/v1/documents/doc1/changesx/query"},
278			// The batch lookup is document-level only; the same segment under a
279			// session change collection is not an endpoint there.
280			{http.MethodPost, "/v1/sessions/sess/documents/doc1/changes/query"},
281		}
282		for _, tc := range cases {
283			t.Run(tc.method+" "+tc.path, func(t *testing.T) {
284				r := httptest.NewRequest(tc.method, tc.path, strings.NewReader(`{"deviceId":"dev","ids":["a"]}`))
285				r.Header.Set("Content-Type", "application/json")
286				w := httptest.NewRecorder()
287				h.ServeHTTP(w, r)
288				if w.Code != http.StatusBadRequest {
289					t.Fatalf("status = %d want 400 body = %s", w.Code, w.Body.String())
290				}
291				if ct := w.Header().Get("Content-Type"); !strings.HasPrefix(ct, "application/json") {
292					t.Fatalf("content type = %q, want JSON", ct)
293				}
294				if loc := w.Header().Get("Location"); loc != "" {
