38	func TestSessionCompactEndToEnd(t *testing.T) {
39		h, _ := newTestHandler(t)
40		createSessionViaHTTP(t, h, "dev", "sess")
41		seedDoc(t, h, "doc", 3)
42		snapshotViaHTTP(t, h, "doc", 2) // boundary 2
43	
44		// The body only has to be one legal JSON value; a stray deviceId is
45		// ignored and never overrides the session's owning device.
46		w := postSessionCompact(t, h, "sess", "doc", `{"deviceId":"someone-else"}`)
47		if w.Code != http.StatusOK {
48			t.Fatalf("compact = %d %s", w.Code, w.Body.String())
49		}
50		if got := w.Body.String(); got != "{\"boundary\":2,\"removed\":2}\n" {
51			t.Fatalf("compact body = %q", got)
52		}
53		if ct := w.Header().Get("Content-Type"); ct != "application/json" {
54			t.Fatalf("compact content type = %q", ct)
55		}
56	
57		// Only the online tail survives, readable through the session view.
58		_, body := doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc/changes?after=0")
59		rows := body["changes"].([]any)
60		if len(rows) != 1 {
61			t.Fatalf("changes after compact = %v", rows)
62		}
63		row := rows[0].(map[string]any)
64		if row["id"] != "c3" || row["deviceId"] != "dev" || int64(row["cursor"].(float64)) != 3 {
65			t.Fatalf("remaining row = %v", row)
66		}
67		if next := int64(body["nextCursor"].(float64)); next != 3 {
68			t.Fatalf("nextCursor = %d, want 3", next)
69		}
70	
71		// An empty page inside the trimmed range reports the boundary.
72		_, body = doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc/changes?after=3")
73		if got := body["changes"].([]any); len(got) != 0 {
74			t.Fatalf("changes after 3 = %v", got)
75		}
76		if next := int64(body["nextCursor"].(float64)); next != 3 {
77			t.Fatalf("nextCursor after 3 = %d, want 3", next)
78		}
79	
80		// Repeating the compaction is not an error: same boundary, zero removed.
81		if w := postSessionCompact(t, h, "sess", "doc", `{}`); w.Code != http.StatusOK ||
82			w.Body.String() != "{\"boundary\":2,\"removed\":0}\n" {
83			t.Fatalf("re-compact = %d %q", w.Code, w.Body.String())
84		}
85	
86		// New changes committed through the session continue the never-reset
87		// cursor space at cursor 4.
88		w2, body := postJSON(t, h, sessionChangesPath("sess", "doc"), map[string]any{
89			"changes": []any{map[string]any{"id": "c4", "payload": map[string]any{"n": 4}}},
90		})
91		if w2.Code != http.StatusOK {
92			t.Fatalf("session post after compact: %d %s", w2.Code, w2.Body.String())
93		}
94		result := body["results"].([]any)[0].(map[string]any)
95		if result["created"] != true || int64(result["cursor"].(float64)) != 4 {
96			t.Fatalf("new change result = %v, want created cursor 4", result)
97		}
98	}
