100	// Every legal JSON value is an acceptable compaction body; its content never
101	// affects the result.
102	func TestSessionCompactAcceptsAnyJSONBody(t *testing.T) {
103		h, _ := newTestHandler(t)
104		createSessionViaHTTP(t, h, "dev", "sess")
105		seedDoc(t, h, "doc", 2)
106		snapshotViaHTTP(t, h, "doc", 2)
107	
108		first := true
109		for _, raw := range []string{
110			`{}`,
111			`{"deviceId":"dev"}`,
112			`{"unexpected":["nested", 1, true, null]}`,
113			`[]`,
114			`[1, {"a":2}]`,
115			`"a string"`,
116			`123`,
117			`true`,
118			`null`,
119		} {
120			w := postSessionCompact(t, h, "sess", "doc", raw)
121			if w.Code != http.StatusOK {
122				t.Fatalf("body %s = %d %s", raw, w.Code, w.Body.String())
123			}
124			// The first legal body trims both rows; every later legal body is an
125			// idempotent repeat against the same boundary.
126			want := "{\"boundary\":2,\"removed\":0}\n"
127			if first {
128				want = "{\"boundary\":2,\"removed\":2}\n"
129			}
130			first = false
131			if got := w.Body.String(); got != want {
132				t.Fatalf("body %s -> %q, want %q", raw, got, want)
133			}
134		}
135	}
