244	func TestSessionCompactGateOrdering(t *testing.T) {
245		h, _ := newTestHandler(t)
246		createSessionViaHTTP(t, h, "dev", "sess")
247		seedDoc(t, h, "doc", 1)
248		snapshotViaHTTP(t, h, "doc", 1)
249		// Revoke the session owner's permission on a second document.
250		w, _ := postJSON(t, h, "/v1/documents/doc2/permissions", map[string]any{"deviceId": "dev", "action": "revoke"})
251		if w.Code != http.StatusOK {
252			t.Fatal(w.Body.String())
253		}
254	
255		// A deleted session is a 404, even with an otherwise valid body.
256		gw, _ := postJSON(t, h, "/v1/devices/dev/sessions", map[string]any{"sessionId": "gone"})
257		if gw.Code != http.StatusOK {
258			t.Fatalf("create gone session: %d %s", gw.Code, gw.Body.String())
259		}
260		dw, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev/sessions/gone")
261		if dw.Code != http.StatusOK {
262			t.Fatalf("delete session = %d %s", dw.Code, dw.Body.String())
263		}
264		if w := postSessionCompact(t, h, "gone", "doc", `{}`); w.Code != http.StatusNotFound {
265			t.Fatalf("deleted session = %d %s", w.Code, w.Body.String())
266		}
267	
268		// Revoked permission is a 403 after the shape and session checks pass.
269		if w := postSessionCompact(t, h, "sess", "doc2", `{}`); w.Code != http.StatusForbidden {
270			t.Fatalf("revoked = %d %s", w.Code, w.Body.String())
271		}
272	
273		// The rejected compaction wrote nothing: doc2 has no boundary and an
274		// authorized document is untouched; doc was never compacted.
275		if w := postSessionCompact(t, h, "sess", "doc", `{}`); w.Code != http.StatusOK ||
276			w.Body.String() != "{\"boundary\":1,\"removed\":1}\n" {
277			t.Fatalf("doc compact after rejected doc2 compact = %d %q", w.Code, w.Body.String())
