281	func TestSessionCompactTrimmedIdentityAndMerge(t *testing.T) {
282		h, _ := newTestHandler(t)
283		createSessionViaHTTP(t, h, "dev", "sess")
284		seedDoc(t, h, "doc", 2)
285		snapshotViaHTTP(t, h, "doc", 2)
286		if w := postSessionCompact(t, h, "sess", "doc", `{}`); w.Code != http.StatusOK {
287			t.Fatalf("compact = %d %s", w.Code, w.Body.String())
288		}
289	
290		// Re-posting a trimmed id through the session commit with the same source
291		// and payload is idempotent: created=false with the first cursor.
292		w, body := postJSON(t, h, sessionChangesPath("sess", "doc"), map[string]any{
293			"changes": []any{map[string]any{"id": "c1", "payload": map[string]any{"n": 1}}},
294		})
295		if w.Code != http.StatusOK {
296			t.Fatalf("trimmed replay = %d %s", w.Code, w.Body.String())
297		}
298		result := body["results"].([]any)[0].(map[string]any)
299		if result["created"] != false || int64(result["cursor"].(float64)) != 1 {
300			t.Fatalf("trimmed replay result = %v, want created=false cursor 1", result)
301		}
302	
303		// A differing payload through the session commit is a 409 with zero
304		// writes.
305		w, _ = postJSON(t, h, sessionChangesPath("sess", "doc"), map[string]any{
306			"changes": []any{map[string]any{"id": "c1", "payload": map[string]any{"n": 99}}},
307		})
308		if w.Code != http.StatusConflict {
309			t.Fatalf("payload mismatch = %d, want 409", w.Code)
310		}
311	
312		// A session merge whose base cursor is below the boundary cannot run the
313		// conflict check: 400 and zero writes.
314		if w, _ := postSessionMerge(t, h, "sess", "doc", map[string]any{
315			"baseCursor": 0,
316			"change":     map[string]any{"id": "m0", "payload": map[string]any{"k": 1}},
317		}); w.Code != http.StatusBadRequest {
318			t.Fatalf("merge base below boundary = %d, want 400", w.Code)
319		}
320	
321		// No cursor was allocated by either rejection.
322		_, body = doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc/changes?after=0")
323		if got := body["changes"].([]any); len(got) != 0 {
324			t.Fatalf("changes after rejections = %v", got)
325		}
326	}
