328	// Compaction is not a change: a session long poll parked at the tail is not
329	// woken by it and only returns when its own wait deadline expires.
330	func TestSessionCompactDoesNotWakeSessionPoll(t *testing.T) {
331		h, _ := newTestHandler(t)
332		createSessionViaHTTP(t, h, "dev", "sess")
333		seedDoc(t, h, "doc", 3)
334		snapshotViaHTTP(t, h, "doc", 2)
335	
336		type pollResult struct {
337			body    map[string]any
338			elapsed time.Duration
339		}
340		done := make(chan pollResult, 1)
341		go func() {
342			start := time.Now()
343			_, body := doRequest(t, h, http.MethodGet,
344				"/v1/sessions/sess/documents/doc/changes/poll?after=3&waitMs=300")
345			done <- pollResult{body, time.Since(start)}
346		}()
347		time.Sleep(50 * time.Millisecond)
348		if w := postSessionCompact(t, h, "sess", "doc", `{}`); w.Code != http.StatusOK {
349			t.Fatalf("compact = %d %s", w.Code, w.Body.String())
350		}
351		select {
352		case got := <-done:
353			if got.body["timedOut"] != true {
354				t.Fatalf("poll timedOut = %v", got.body)
355			}
356			if next := int64(got.body["nextCursor"].(float64)); next != 3 {
357				t.Fatalf("poll nextCursor = %d, want 3", next)
358			}
359			if got.elapsed < 200*time.Millisecond {
360				t.Fatalf("poll returned after %v: the compaction woke it", got.elapsed)
361			}
362		case <-time.After(3 * time.Second):
363			t.Fatal("poll did not return")
364		}
365	}
366	
367	func TestSessionCompactRestart(t *testing.T) {
368		dir := t.TempDir()
369		dbPath := filepath.Join(dir, "sync.db")
370	
371		open := func(t *testing.T) (http.Handler, *app.App) {
372			t.Helper()
373			s, err := app.Open(dbPath)
374			if err != nil {
375				t.Fatal(err)
376			}
377			return NewHandler(s), s
378		}
379	
380		h, s := open(t)
381		createSessionViaHTTP(t, h, "dev", "sess")
382		seedDoc(t, h, "doc", 3)
383		snapshotViaHTTP(t, h, "doc", 2)
384		if w := postSessionCompact(t, h, "sess", "doc", `{}`); w.Code != http.StatusOK ||
385			w.Body.String() != "{\"boundary\":2,\"removed\":2}\n" {
386			t.Fatalf("compact = %d %q", w.Code, w.Body.String())
387		}
388		if err := s.Close(); err != nil {
389			t.Fatal(err)
390		}
391	
392		h2, s2 := open(t)
393		defer func() { _ = s2.Close() }()
394	
395		// The session must be re-established through HTTP after restart (the
396		// device and session rows are durable; this is the same create call,
397		// reporting created=false).
398		w, _ := postJSON(t, h2, "/v1/devices/dev/sessions", map[string]any{"sessionId": "sess"})
399		if w.Code != http.StatusOK {
400			t.Fatalf("re-create session after restart: %d %s", w.Code, w.Body.String())
401		}
402	
403		// The boundary, reads and idempotency decisions survive the restart.
404		if w := postSessionCompact(t, h2, "sess", "doc", `{}`); w.Code != http.StatusOK ||
405			w.Body.String() != "{\"boundary\":2,\"removed\":0}\n" {
406			t.Fatalf("re-compact after restart = %d %q", w.Code, w.Body.String())
407		}
408		_, body := doRequest(t, h2, http.MethodGet, "/v1/sessions/sess/documents/doc/changes?after=0")
409		rows := body["changes"].([]any)
410		if len(rows) != 1 || rows[0].(map[string]any)["id"] != "c3" {
411			t.Fatalf("changes after restart = %v", rows)
412		}
413		w2, body := postJSON(t, h2, sessionChangesPath("sess", "doc"), map[string]any{
414			"changes": []any{map[string]any{"id": "c1", "payload": map[string]any{"n": 1}}},
415		})
416		if w2.Code != http.StatusOK {
417			t.Fatalf("trimmed replay after restart = %d %s", w2.Code, w2.Body.String())
418		}
419		result := body["results"].([]any)[0].(map[string]any)
420		if result["created"] != false || int64(result["cursor"].(float64)) != 1 {
421			t.Fatalf("trimmed replay result after restart = %v", result)
422		}
423	}
